function tstr(s){
  if (Object.prototype.hasOwnProperty.call(I18N, s)) return I18N[s];
  for (var i=0;i<I18N_RULES.length;i++){ if (I18N_RULES[i][0].test(s)) return s.replace(I18N_RULES[i][0], I18N_RULES[i][1]); }
  return null;
}
function applyLang(){
  var root = document.body;
  var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode:function(n){
    return /^(SCRIPT|STYLE|NOSCRIPT)$/.test(n.parentNode.nodeName) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; }});
  var n, nodes=[]; while ((n=w.nextNode())) nodes.push(n);
  for (var i=0;i<nodes.length;i++){
    var node = nodes[i];
    if (node.__en === undefined) node.__en = node.nodeValue;
    var src = node.__en;
    if (LANG === 'en'){ if (node.nodeValue !== src) node.nodeValue = src; continue; }
    var key = src.replace(/\s+/g,' ').trim();
    if (!key) continue;
    var out = tstr(key);
    if (out === null) { if (node.nodeValue !== src) node.nodeValue = src; continue; }
    var lead = src.match(/^\s*/)[0], tail = src.match(/\s*$/)[0];
    node.nodeValue = lead + out + tail;
  }
  var titled = document.querySelectorAll('[title]');
  for (var j=0;j<titled.length;j++){
    var e = titled[j];
    if (e.__tEn === undefined) e.__tEn = e.getAttribute('title');
    if (LANG === 'en'){ e.setAttribute('title', e.__tEn); continue; }
    var t = tstr(e.__tEn.replace(/\s+/g,' ').trim());
    e.setAttribute('title', t === null ? e.__tEn : t);
  }
  document.documentElement.lang = LANG;
  var lb = document.getElementById('langbtn');
  if (lb) lb.innerHTML = '<span class="'+(LANG==='en'?'on':'')+'">EN</span><span class="'+(LANG==='es'?'on':'')+'">ES</span>';
}
function setLang(l){ LANG = l; if (typeof afterLang === 'function') afterLang(); else applyLang(); }
function tgLang(){ setLang(LANG === 'en' ? 'es' : 'en'); }
